int ceph_verify_authorizer_reply(struct ceph_auth_client *ac, struct ceph_authorizer *a, size_t len)
{
    struct ceph_auth_handshake *hs = &ac->handshake;
    struct ceph_enc_message *enc_msg;
    int ret;

    enc_msg = ceph_get_ticket_handler(ac, a->service);
    if (IS_ERR(enc_msg))
        return PTR_ERR(enc_msg);

    ret = ceph_decrypt_message(enc_msg, hs->session_key.data, hs->session_key.length);
    if (ret < 0)
        return ret;

    if (ret != len)
        return -EINVAL;

    if (memcmp(a->nonce, enc_msg->nonce, CEPH_AUTH_NONCE_SIZE) != 0)
        return -EINVAL;

    ceph_log_auth_info(ac, "authorizer reply verified successfully");

    return 0;
}

int ceph_auth_verify_authorizer_reply(struct ceph_auth_client *ac, struct ceph_authorizer *a, size_t len) {
    struct ceph_auth_ticket_handler *handler;
    int ret;

    handler = ceph_auth_get_ticket_handler(ac, a->service);
    if (!handler) {
        return -ENOENT;
    }

    ret = handler->decrypt_reply(handler, a->reply_buf, len, a->decrypted_reply, &a->decrypted_len);
